    #[test]
    fn parser_rejects_nonliteral_flags_unknown_keys_and_bad_selectors() {
        let request = session()["play_request"]["params"].clone();
        for key in ["session", "progressive"] {
            for value in [
                json!(false),
                Value::Null,
                json!(1),
                json!("true"),
                json!({}),
            ] {
                let mut bad = request.clone();
                bad[key] = value;
                assert!(matches!(
                    LocalRequest::parse(&bad),
                    Err(LocalError::InvalidRequest)
                ));
            }
        }
        for key in ["version", "include_paths", "path", "other"] {
            let mut bad = request.clone();
            bad[key] = json!(true);
            assert!(LocalRequest::parse(&bad).is_err());
        }
        for value in [
            "",
            ".",
            "..",
            "parent/folder",
            "a\\b",
            "line\nfeed",
            "bad\u{85}",
        ] {
            let mut bad = request.clone();
            bad["source"] = json!(value);
            assert!(LocalRequest::parse(&bad).is_err());
        }
        for value in ["PAGE", "two words", "page:123", ""] {
            let mut bad = request.clone();
            bad["runtime"] = json!(value);
            assert!(LocalRequest::parse(&bad).is_err());
        }
        for operation in ["sources_request", "connect_request"] {
            for key in ["session", "progressive"] {
                let mut bad = base()[operation]["params"].clone();
                bad[key] = json!(true);
                assert!(LocalRequest::parse(&bad).is_err());
            }
        }
        let mut colon = request;
        colon["source"] = json!("Films: evening");
        assert!(LocalRequest::parse(&colon).is_ok());
        colon["source"] = json!("я".repeat(257));
        assert!(LocalRequest::parse(&colon).is_err());
    }

    #[test]
    fn canonical_lookup_reuses_source_and_read_only_miss_does_not_connect() {
        let mut request = base()["play_request"]["params"].clone();
        request["source"] = json!("/var/media/Movies");
        let request = LocalRequest::parse(&request).unwrap();
        assert!(matches!(
            select_source(
                &request,
                &SourceSnapshot {
                    lookup_path: None,
                    sources: &[]
                }
            ),
            Ok(SourceSelection::LookupPath)
        ));
        let mut source = source();
        source.canonical_path = Some("/private/var/media/Movies".into());
        let sources = [source];
        match select_source(
            &request,
            &SourceSnapshot {
                lookup_path: Some("/var/media/Movies"),
                sources: &sources,
            },
        )
        .unwrap()
        {
            SourceSelection::Selected(found) => assert_eq!(found.id, "source-123"),
            _ => panic!("existing canonical root must not reconnect"),
        }
        assert!(matches!(
            select_source(
                &request,
                &SourceSnapshot {
                    lookup_path: Some("/var/media/Movies"),
                    sources: &[]
                }
            ),
            Ok(SourceSelection::ConnectPath)
        ));
        let query = LocalRequest::parse(&base()["lookup_request"]["params"]).unwrap();
        match select_source(
            &query,
            &SourceSnapshot {
                lookup_path: Some("/var/media/Movies"),
                sources: &[],
            },
        )
        .unwrap()
        {
            SourceSelection::List(rows) => assert!(rows.is_empty()),
            _ => panic!("read-only miss must not attach a folder"),
        }
    }

